#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_bf16.h>
#include <algorithm>
#include <climits>

__global__ void conv2d_3x3_bf16_kernel(
    const __nv_bfloat16* __restrict__ x,
    const __nv_bfloat16* __restrict__ w,
    __nv_bfloat16* __restrict__ y,
    int N, int C_in, int H_in, int W_in,
    int C_out, int H_out, int W_out,
    long long total) {
  constexpr int TILE = 16;           // threads per spatial dim
  constexpr int OUT = TILE * 2;      // 2x2 register blocking -> 32x32 output tile
  constexpr int IN_TILE = OUT + 2;   // halo for 3x3 kernel
  constexpr int CO_TILE = 4;         // output channels computed per block
  constexpr int SMEM_ELEMS = 3 * IN_TILE * IN_TILE;
  __shared__ float s_x[SMEM_ELEMS];
  __shared__ float s_w[CO_TILE * 27];
  const int ow0 = blockIdx.x * OUT;
  const int oh0 = blockIdx.y * OUT;
  const int co_tiles = (C_out + CO_TILE - 1) / CO_TILE;
  const int co0 = (blockIdx.z % co_tiles) * CO_TILE;
  const int n   = blockIdx.z / co_tiles;
  const int tid = threadIdx.x;
  // Cooperatively stage the haloed input tile (all 3 input channels)
  // into shared memory so neighboring outputs reuse activations.
  for (int i = tid; i < SMEM_ELEMS; i += blockDim.x) {
    int c   = i / (IN_TILE * IN_TILE);
    int rem = i % (IN_TILE * IN_TILE);
    int r   = rem / IN_TILE;
    int col = rem % IN_TILE;
    int ih = oh0 + r;
    int iw = ow0 + col;
    float v = 0.0f;
    if (ih < H_in && iw < W_in) {
      long long off = (((long long)n * C_in + c) * H_in + ih) * W_in + iw;
      v = __bfloat162float(x[off]);
    }
    s_x[i] = v;
  }
  // Stage CO_TILE output channels' weights once per block. The staged
  // input tile is now reused across all four output channels, greatly
  // improving shared-memory reuse (each activation feeds CO_TILE FMAs).
  for (int i = tid; i < CO_TILE * 27; i += blockDim.x) {
    int kc = i / 27;
    int co = co0 + kc;
    s_w[i] = (co < C_out)
                 ? __bfloat162float(w[(long long)co * C_in * 9 + (i - kc * 27)])
                 : 0.0f;
  }
  __syncthreads();
  const int tx = tid % TILE;
  const int ty = tid / TILE;
  const int ty2 = ty * 2;
  const int tx2 = tx * 2;
  const int oh = oh0 + ty2;
  const int ow = ow0 + tx2;
  if (oh >= H_out || ow >= W_out) return;
  // 2x2 register blocking per output channel. The 4x4 input patch per
  // channel is loaded into registers once and reused across all CO_TILE
  // output channels and all four spatial accumulators, cutting both
  // shared-memory traffic and global-memory traffic per output.
  float acc[CO_TILE][2][2];
  #pragma unroll
  for (int kc = 0; kc < CO_TILE; ++kc) {
    acc[kc][0][0] = 0.0f;
    acc[kc][0][1] = 0.0f;
    acc[kc][1][0] = 0.0f;
    acc[kc][1][1] = 0.0f;
  }
  #pragma unroll
  for (int ci = 0; ci < 3; ++ci) {
    const float* s_c = s_x + ci * IN_TILE * IN_TILE;
    float v[4][4];
    #pragma unroll
    for (int r = 0; r < 4; ++r) {
      const float* s_r = s_c + (ty2 + r) * IN_TILE + tx2;
      #pragma unroll
      for (int c = 0; c < 4; ++c) {
        v[r][c] = s_r[c];
      }
    }
    #pragma unroll
    for (int kc = 0; kc < CO_TILE; ++kc) {
      const float* w_c = s_w + kc * 27 + ci * 9;
      #pragma unroll
      for (int kh = 0; kh < 3; ++kh) {
        #pragma unroll
        for (int kw = 0; kw < 3; ++kw) {
          const float wv = w_c[kh * 3 + kw];
          acc[kc][0][0] += v[kh][kw] * wv;
          acc[kc][0][1] += v[kh][kw + 1] * wv;
          acc[kc][1][0] += v[kh + 1][kw] * wv;
          acc[kc][1][1] += v[kh + 1][kw + 1] * wv;
        }
      }
    }
  }
  #pragma unroll
  for (int kc = 0; kc < CO_TILE; ++kc) {
    const int co = co0 + kc;
    if (co >= C_out) break;
    long long out = (((long long)n * C_out + co) * H_out + oh) * W_out + ow;
    y[out] = __float2bfloat16(acc[kc][0][0]);
    if (ow + 1 < W_out) {
      y[out + 1] = __float2bfloat16(acc[kc][0][1]);
    }
    if (oh + 1 < H_out) {
      y[out + W_out] = __float2bfloat16(acc[kc][1][0]);
      if (ow + 1 < W_out) {
        y[out + W_out + 1] = __float2bfloat16(acc[kc][1][1]);
      }
    }
  }
}

at::Tensor conv2d_bf16_forward(at::Tensor x, at::Tensor w) {
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kBFloat16 && w.scalar_type() == at::kBFloat16,
              "x and w must be bfloat16");
  TORCH_CHECK(x.dim() == 4 && w.dim() == 4, "x and w must be 4D");

  auto xc = x.contiguous();
  auto wc = w.contiguous();

  int64_t N = xc.size(0);
  int64_t C_in = xc.size(1);
  int64_t H_in = xc.size(2);
  int64_t W_in = xc.size(3);
  int64_t C_out = wc.size(0);

  TORCH_CHECK(wc.size(1) == C_in, "weight/input channel mismatch");
  TORCH_CHECK(C_in == 3, "this kernel is specialized for C_in == 3");
  TORCH_CHECK(wc.size(2) == 3 && wc.size(3) == 3, "kernel size must be 3x3");
  TORCH_CHECK(H_in >= 3 && W_in >= 3, "input must be at least 3x3");
  TORCH_CHECK(N <= INT_MAX && C_in <= INT_MAX && H_in <= INT_MAX && W_in <= INT_MAX &&
              C_out <= INT_MAX, "tensor too large");

  int64_t H_out = H_in - 2;
  int64_t W_out = W_in - 2;
  auto y = at::empty({N, C_out, H_out, W_out}, xc.options());

  long long total = (long long)N * C_out * H_out * W_out;
  if (total == 0) {
    return y;
  }

  const __nv_bfloat16* xp = reinterpret_cast<const __nv_bfloat16*>(xc.data_ptr<at::BFloat16>());
  const __nv_bfloat16* wp = reinterpret_cast<const __nv_bfloat16*>(wc.data_ptr<at::BFloat16>());
  __nv_bfloat16* yp = reinterpret_cast<__nv_bfloat16*>(y.data_ptr<at::BFloat16>());

  const int TILE = 16;
  const int OUT = TILE * 2;
  dim3 threads(TILE * TILE);
  int tiles_w = (int)((W_out + OUT - 1) / OUT);
  int tiles_h = (int)((H_out + OUT - 1) / OUT);
  int co_tiles = (int)((C_out + 3) / 4);
  dim3 blocks(tiles_w, tiles_h, (int)(N * co_tiles));
  cudaStream_t stream = at::cuda::getCurrentCUDAStream();
  conv2d_3x3_bf16_kernel<<<blocks, threads, 0, stream>>>(
      xp, wp, yp,
      (int)N, (int)C_in, (int)H_in, (int)W_in,
      (int)C_out, (int)H_out, (int)W_out,
      total);
  TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUDA kernel launch failed");

  return y;
}
'''

